public class PaymentProcessor
{
    public virtual void Process() => Console.WriteLine("Processing payment");
}

public class CreditCardProcessor : PaymentProcessor
{
    public override void Process() => Console.WriteLine("Processing credit card");
}

public class PayPalProcessor : PaymentProcessor
{
    public override void Process() => Console.WriteLine("Processing PayPal");
}

// Runtime polymorphism
PaymentProcessor processor;
processor = new CreditCardProcessor();
processor.Process(); // Processing credit card

processor = new PayPalProcessor();
processor.Process(); // Processing PayPal
